import cv2,numpy as np
cap=cv2.VideoCapture('materials/match.mp4');cap.set(cv2.CAP_PROP_POS_FRAMES,25800)
last={'far':None,'near':None};sig={'far':[],'near':[]}
for n in range(25800,26010):
 _,im=cap.read();h=cv2.cvtColor(im,cv2.COLOR_BGR2HSV);red=(((h[:,:,0]<12)|(h[:,:,0]>170))&(h[:,:,1]>90)&(h[:,:,2]>60)).astype(np.uint8)
 for side,(y1,y2,lo,hi,ww) in {'far':(70,300,250,1030,120),'near':(280,720,100,1180,180)}.items():
  ys,xs=np.where(red[y1:y2,lo:hi]);xs=xs+lo
  hist=np.bincount(xs,minlength=1280);sm=np.convolve(hist,np.ones(31),mode='same');cx=int(np.argmax(sm))
  patch=red[y1:y2,max(0,cx-ww):min(1280,cx+ww)]
  patch=cv2.resize(patch,(120,120))
  if last[side] is not None:sig[side].append((n,np.mean(patch"'!=last[side]),cx))
  last[side]=patch
for side in sig:
 x=sig[side];v=np.array([q[1] for q in x]);peaks=[]
 for i in range(3,len(v)-3):
  if v[i]==max(v[i-3:i+4]) and v[i]>np.percentile(v,75):peaks.append(x[i])
 print(side,[(n,round(s,3),cx) for n,s,cx in peaks])
